import{_ as t,o as e,c as a,a5 as n}from"./chunks/framework.BjM_ivYE.js";const r="/RBQ/images/app/home-vision.pc.ko.png",s="/RBQ/images/app/dashboard-detail.pc.ko.png",u=JSON.parse('{"title":"개발자 모드","description":"","frontmatter":{"layout":"doc","outline":"deep","title":"개발자 모드"},"headers":[],"relativePath":"ko/manual/gui/developer-mode.md","filePath":"ko/manual/gui/developer-mode.md","lastUpdated":1790654982000}'),d={name:"ko/manual/gui/developer-mode.md"};function c(i,o,g,l,h,p){return e(),a("div",null,[...o[0]||(o[0]=[n('<h1 id="개발자-모드" tabindex="-1">개발자 모드 <a class="header-anchor" href="#개발자-모드" aria-label="Permalink to &quot;개발자 모드&quot;">​</a></h1><p>앱은 기본적으로 <strong>운용자 등급</strong>으로 동작합니다. 개발자 모드를 켜면 진단·설정·정비 기능이 화면에 추가로 나타납니다. 이 페이지에 <strong>개발자 모드로만 열리는 것을 전부 모아 두었습니다</strong> — 다른 페이지들은 일반 운용에 필요한 것만 다룹니다.</p><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">주의</p><p>개발자 모드에서는 <strong>평소의 안전장치를 거치지 않고 로봇을 움직이는 명령</strong>(관절 잠금, 강제 자세)과 연결·자세·주행을 끊을 수 있는 전원 조작이 열립니다. 필요할 때만 켜고, 조작 전에 각 항목의 경고를 읽으세요.</p></div></div><h2 id="turn-on" tabindex="-1">켜고 끄기 <a class="header-anchor" href="#turn-on" aria-label="Permalink to &quot;켜고 끄기 {#turn-on}&quot;">​</a></h2><ol><li>허브 오른쪽 위의 프로필 버튼을 누릅니다.</li><li><strong>개발자 모드</strong> 토글을 켭니다. 부제에 <em>켤 때 암호 필요</em> 라고 적혀 있습니다.</li><li><strong>개발자 모드 암호</strong> 창에 암호를 입력하고 <strong>확인</strong>을 누릅니다. 틀리면 <em>암호가 올바르지 않습니다</em> 가 표시되고 입력칸이 비워집니다.</li></ol><p>토글을 끄면 즉시 운용자 등급으로 돌아갑니다.</p><div class="sb sb-warning"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">경고</p><p>암호는 <strong>Rainbow Robotics 에서 개별로 발급</strong>합니다. 이 매뉴얼에는 적지 않으며, 받은 암호를 외부에 알리지 마세요. 필요하시면 <a href="/RBQ/ko/manual/support/">기술지원 요청</a>으로 문의하세요.</p></div></div><h3 id="by-account" tabindex="-1">계정으로 켜지는 경우 <a class="header-anchor" href="#by-account" aria-label="Permalink to &quot;계정으로 켜지는 경우 {#by-account}&quot;">​</a></h3><p>프로필 메뉴의 <code>접근 코드로 로그인</code>으로 로그인하면 등급은 <strong>계정을 따릅니다.</strong> 로그인 중에는 프로필 메뉴에 개발자 모드 토글 대신 계정과 레벨이 표시됩니다. 일반 등급으로 돌아가려면 같은 메뉴의 <code>로그아웃</code>을 누르세요.</p><h2 id="what-changes" tabindex="-1">화면별로 무엇이 늘어나나 <a class="header-anchor" href="#what-changes" aria-label="Permalink to &quot;화면별로 무엇이 늘어나나 {#what-changes}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>화면</th><th>개발자 모드에서 추가되는 것</th></tr></thead><tbody><tr><td><a href="#control-home">제어 홈</a></td><td><code>조종</code> 팝오버의 외부 조종 토글</td></tr><tr><td><a href="#motion">모션 명령</a></td><td><strong>AI 모션</strong> 그룹 (학습 기반 보행) · <strong>포지션 제어</strong> 그룹 (강제 자세)</td></tr><tr><td><a href="#gamepad">게임패드</a></td><td>감도·데드존, 버튼 매핑, 외부 조종, 개발자 옵션, 진단·마법사</td></tr><tr><td><a href="#vision">카메라 · 비전</a></td><td>카메라 보정(<code>비전</code> 팝오버 자체는 모든 등급에서 열립니다)</td></tr><tr><td><a href="#dashboard">대시보드</a></td><td><strong>로봇</strong> · <strong>비전</strong> 탭, 요약의 전원 추가</td></tr><tr><td><a href="#settings">설정</a></td><td>카메라 캘리브레이션 사용</td></tr><tr><td><a href="#connection">연결</a></td><td>안드로이드·iOS 의 <code>주소로 연결</code> 카드 · <code>Vision PC IP (선택)</code> 칸</td></tr><tr><td><a href="#emergency">비상 정지</a></td><td>포지션 제어를 통한 강제 복구</td></tr><tr><td><a href="#maintenance">정비</a></td><td><strong>화면 전체가 개발자 모드 전용</strong> — 허브의 <code>정비</code> 타일</td></tr><tr><td>로그</td><td><strong>없음</strong> — 이 화면은 등급에 따라 달라지지 않습니다</td></tr></tbody></table><h2 id="control-home" tabindex="-1">제어 홈 <a class="header-anchor" href="#control-home" aria-label="Permalink to &quot;제어 홈 {#control-home}&quot;">​</a></h2><ul><li><strong>조종</strong> 팝오버에 <strong>외부 조종 (SLAM·SDK)</strong> 토글이 추가되어 조종권을 외부 프로그램에 넘길 수 있습니다. 켜져 있는 동안 상단바에 <code>SLAM</code> 칩이 표시되며, 그 칩으로 다시 끕니다.</li></ul><p>→ <a href="/RBQ/ko/manual/gui/control-home.html">제어 홈</a></p><h2 id="motion" tabindex="-1">모션 명령 — AI 모션 · 포지션 제어 <a class="header-anchor" href="#motion" aria-label="Permalink to &quot;모션 명령 — AI 모션 · 포지션 제어 {#motion}&quot;">​</a></h2><p><strong>모션 선택</strong> 그리드에 <strong>AI 모션</strong> 그룹과 <strong>포지션 제어</strong> 그룹이 추가됩니다.</p><p><strong>AI 모션</strong>은 학습 기반 보행입니다 — <code>AI Pronk</code> · <code>AI Bound</code> · <code>AI Pace</code> · <code>AI Run</code> · <code>AI 2Leg L</code> · <code>AI 2Leg R</code> · <code>AI 2Leg F</code> · <code>AI 3Leg HL</code>. 일반 사용자에게는 그룹 자체가 보이지 않습니다.</p><p><strong>포지션 제어</strong> — <code>Lock Joints</code> · <code>Position Sit</code> · <code>Position Stand</code> — 는 일반 전환을 거치지 않고 자세를 강제합니다. 같은 항목이 <code>SIT</code> 길게 누르기 목록에도 있습니다. 휠 로봇에서는 <strong>정밀·보정</strong> 그룹에 <code>HIGH SPEED</code> 도 추가됩니다.</p><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">주의</p><p>포지션 제어는 궤적 없이 자세를 바꿉니다. <strong>평지에서 로봇이 바닥에 있을 때만</strong> 쓰세요. 일반 복구가 통하지 않을 때를 위한 수단입니다.</p></div></div><p>→ <a href="/RBQ/ko/manual/gui/motion-commands.html">모션 명령</a> · <a href="/RBQ/ko/manual/gui/emergency.html">비상 정지</a></p><h2 id="gamepad" tabindex="-1">게임패드 <a class="header-anchor" href="#gamepad" aria-label="Permalink to &quot;게임패드 {#gamepad}&quot;">​</a></h2><p><strong>앱 설정 › 게임패드</strong>에 아래가 추가됩니다.</p><p><strong>반응</strong></p><ul><li><code>게임패드 감도</code> — 물리 스틱의 입력 응답 곡선(가상 조이스틱 설정과 별개).</li><li><code>데드존</code> — 중심 무시 범위. 기기 자체 데드존에 추가로 적용됩니다.</li></ul><p><strong><code>버튼 매핑</code></strong> — 컨트롤러 그림에서 버튼을 탭해 로봇 모션을 할당합니다. 십자키와 스틱 가운데 버튼도 매핑할 수 있습니다. 매핑된 버튼은 그림 아래에 목록으로 나오고 <code>×</code>로 지웁니다. 매핑하려면 컨트롤러가 연결돼 있어야 하며, 버튼을 누르면 그림에 불이 들어옵니다.</p><p><strong><code>외부 조종 (SLAM·SDK)</code></strong> — 로봇 조종권을 외부에 넘깁니다. 스위치는 로봇의 실제 상태를 반영하므로 다른 클라이언트가 바꿔도 함께 갱신됩니다. 제어 홈의 <code>조종</code> 팝오버에도 같은 스위치가 있습니다.</p><p><strong><code>개발자 옵션</code></strong></p><table tabindex="0"><thead><tr><th>항목</th><th>동작</th></tr></thead><tbody><tr><td><code>전체 버튼 전송</code></td><td>OFF = L1/R1만 로봇에 전송(안전 기본값). ON 이면 모든 버튼을 전달해 <strong>L1+B 같은 조합키</strong>가 동작합니다. 개발자 모드로 올라가면 자동으로 켜지고, 일반 사용자로 돌아가면 다시 꺼집니다</td></tr><tr><td><code>원 스틱 모드</code></td><td>한 손 조작 — 좌우 스틱의 가로축만 서로 바꿉니다(세로축은 각 스틱에 남습니다)</td></tr><tr><td><code>크루즈 컨트롤</code></td><td>R3로 크루즈 시작, 십자키 위/아래로 속도 증감. TROT 계열 보행 중에만 동작합니다</td></tr><tr><td><code>발행 주기 — {hz}Hz</code></td><td>조이스틱 프레임 전송 주기(기본 40 Hz). 낮추면 지연이 늘고 높이면 트래픽이 늡니다</td></tr><tr><td><code>입력 진단</code> › <code>진단 열기</code></td><td><code>게임패드 진단</code> 화면 — <code>연결된 기기</code>(이름·VID:PID·축), <code>축 (원시값)</code> 실시간 막대, <code>버튼 이벤트</code> 키코드 로그. 매핑 전에 낯선 컨트롤러를 확인할 때 씁니다</td></tr><tr><td><code>매핑 마법사</code> › <code>마법사 시작</code></td><td>안내에 따라 조작해 이 기기 전용 프로파일을 만듭니다. 미지의 컨트롤러이거나 스틱 배치가 어긋날 때 사용합니다</td></tr><tr><td><code>마법사 프로파일 삭제</code></td><td>연결된 기기에 마법사 프로파일이 있을 때만 표시됩니다. 지우고 자동 인식으로 되돌립니다</td></tr></tbody></table><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">주의</p><p><code>전체 버튼 전송</code>과 <code>크루즈 컨트롤</code>은 버튼 입력에 대한 로봇의 반응을 바꿉니다. 켠 뒤에는 넓은 공간에서 먼저 시험하고, E-STOP 을 바로 누를 수 있는 위치에 두세요.</p></div></div><p>→ <a href="/RBQ/ko/manual/gui/gamepad.html">게임패드</a></p><h2 id="vision" tabindex="-1">카메라 · 비전 <a class="header-anchor" href="#vision" aria-label="Permalink to &quot;카메라 · 비전 {#vision}&quot;">​</a></h2><p><img src="'+r+'" alt="비전 팝오버"></p><p>오른쪽 카드의 <code>비전</code> 줄은 <strong>로봇 쪽 비전 스위치</strong>를 엽니다. 이 팝오버는 모든 등급에서 열립니다 — 내용은 <a href="/RBQ/ko/manual/gui/camera-vision.html">카메라 · 비전</a>을 보세요. 개발자 모드에서 더해지는 것은 맨 아래 카메라 보정 진입점뿐입니다.</p><p>팝오버 맨 아래의 <code>카메라 보정</code>은 카메라 보정 도구를 엽니다. 같은 진입점이 <strong>로봇 설정 › 캘리브레이션 › <code>카메라 캘리브레이션 열기</code></strong> 에도 있습니다. 둘 다 앱에서 카메라 보정이 허용돼 있고 <strong>동시에</strong> 계정이 개발자 등급일 때만 표시됩니다. 진행 중이면 버튼 문구가 <code>카메라 보정 진행 중 — 탭하면 취소</code> / <code>진행 중 — 눌러서 취소</code> 로 바뀝니다.</p><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">주의</p><p>OAK-D 내부 파라미터 보정은 로봇이 <strong>약 10분간 스스로 걸어 다닙니다.</strong> 시작하기 전에 주변을 비우세요.</p></div></div><p>→ <a href="/RBQ/ko/manual/gui/camera-vision.html">카메라 · 비전</a></p><h2 id="dashboard" tabindex="-1">대시보드 <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;대시보드 {#dashboard}&quot;">​</a></h2><p><img src="'+s+'" alt="로봇 상태표"></p><p>제목 아래에 <strong>요약</strong> · <strong>로봇</strong> · <strong>비전</strong> 세 탭이 나타납니다. 요약에는 <strong>전원 정비 ▸</strong>(시스템 카드)가 추가됩니다.</p><p><strong>로봇</strong> 탭의 표:</p><ul><li><strong>전원 · PDU</strong> — 제목에 PDU 배터리 %. 레일별(<strong>TOTAL</strong>, <strong>BAT L</strong>, <strong>BAT R</strong>, <strong>LEGS</strong>, <strong>ADDON</strong>, <strong>EXTERN</strong>, <strong>CHARGE</strong>) 전압·전류·온도·스위치 상태. CHARGE 행 스위치 칸에는 켜진 것의 이름이 적힙니다: <strong>도킹</strong> / <strong>포트</strong>.</li><li><strong>장치 전원 · 12V/5V</strong> — 장치 레일별 ON / OFF.</li><li><strong>IMU</strong> — R(x), P(y), Y(z)의 <strong>ANGLE°</strong>, <strong>GYRO (rad/s)</strong>, <strong>ACC (m/s²)</strong>. 표 아래에 <strong>IMU 캘리브레이션 ▸</strong> 바로가기.</li><li><strong>관절 · JOINT</strong> — 관절마다 <strong>ID</strong>, <strong>STATUS</strong>, <strong>ERR</strong>, <strong>°C B/S</strong>(보드/스테이터 온도), <strong>ANGLE°</strong>. STATUS 는 <em>C·H·R</em> — <strong>C</strong> 연결(<strong>N</strong> 미연결), <strong>H</strong> 원점, <strong>R</strong> 구동. 초록 = 구동·원점 모두, 주황 = 구동만, 빨강 = 그 외. 온도는 60 °C 주황, 70 °C 빨강.</li></ul><p><strong>비전</strong> 탭 — 데몬 연결, 센서 수, <strong>비전 정비 ▸</strong> 가 붙은 비전 프로그램 목록, <strong>비전 센서</strong> 표(STATUS, RGB / IR / 3D fps, EMIT).</p><p>→ <a href="/RBQ/ko/manual/gui/dashboard.html">대시보드</a></p><h2 id="settings" tabindex="-1">설정 <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;설정 {#settings}&quot;">​</a></h2><ul><li><strong>캘리브레이션 › <code>카메라 캘리브레이션 사용</code></strong> — 켜면 아래에 <code>카메라 캘리브레이션 열기</code>가 나타납니다. 지그 외부 파라미터 / OAK-D 내부 파라미터 절차를 실행하며, 진행 상황은 상단 배너에 나옵니다.</li></ul><p>→ <a href="/RBQ/ko/manual/gui/settings.html">설정</a></p><h2 id="connection" tabindex="-1">연결 <a class="header-anchor" href="#connection" aria-label="Permalink to &quot;연결 {#connection}&quot;">​</a></h2><p>안드로이드·iOS 의 <strong>로봇 추가</strong>에 <code>주소로 연결</code> 카드가 나타납니다(웹 빌드·데스크탑 앱·Steam Deck 은 항상 보입니다). 그 아래 접힌 <code>Vision PC IP (선택)</code> 이 있습니다. 비전 PC 가 별도 주소를 쓰는 로봇을 위한 것이며, 비워 두면 로봇 IP 를 그대로 씁니다. 연결하면 로봇 IP 와 함께 그 로봇에 저장됩니다.</p><p>→ <a href="/RBQ/ko/manual/gui/connection.html">연결</a></p><h2 id="emergency" tabindex="-1">비상 정지 — 강제 복구 <a class="header-anchor" href="#emergency" aria-label="Permalink to &quot;비상 정지 — 강제 복구 {#emergency}&quot;">​</a></h2><p>점선 <code>모션</code> 버튼으로 여는 <code>모션 선택</code> 그리드의 <strong>포지션 제어</strong> 는 일반 복구가 통하지 않을 때 쓰는 수단입니다. <code>Lock Joints</code> · <code>Position Sit</code> · <code>Position Stand</code> 는 궤적 없이 자세를 강제하므로, <strong>평지에서 로봇이 바닥에 있을 때만</strong> 사용하세요. 관절 단위 수동 복구 패널은 내부용입니다.</p><p>→ <a href="/RBQ/ko/manual/gui/emergency.html">비상 정지</a></p><h2 id="maintenance" tabindex="-1">정비 — 화면 전체 <a class="header-anchor" href="#maintenance" aria-label="Permalink to &quot;정비 — 화면 전체 {#maintenance}&quot;">​</a></h2><p><strong>정비</strong> 화면은 통째로 개발자 모드 전용입니다. 개발자 모드가 아니면 허브에 <code>정비</code> 타일이 나오지 않고, 경로로 직접 들어와도 제어 홈으로 되돌아갑니다.</p><p>여기의 조작은 <strong>연결을 끊거나, 로봇을 주저앉히거나, 데몬 기동 방식을 바꿉니다.</strong> 누르기 전에 각 경고를 읽으세요.</p><p>→ <a href="/RBQ/ko/manual/gui/maintenance.html">정비</a></p>',56)])])}const b=t(d,[["render",c]]);export{u as __pageData,b as default};
